// DEVDESK-147 / DEVDESK-223 step 3: column 0 of the explorer tree is the
// activity column. The row carries a state, the blink phase is read at render.

func treeLine(t *testing.T, m Model, name string) string {
	t.Helper()
	for _, l := range strings.Split(m.table.View(), "\n") {
		if strings.Contains(l, name) {
			return l
		}
	}
	t.Fatalf("no rendered line holds %q:\n%s", name, m.table.View())
	return ""
}

func anyGlyph(line string) bool {
	if strings.Contains(line, indicator.Glyph(indicator.Running, false)) {
		return true
	}
	for _, s := range indicator.States() {
		if g := indicator.Glyph(s, true); g != "" && strings.Contains(line, g) {
			return true
		}
	}
	return false
}

// deleting returns a loaded model whose "alpha" row has a delete in flight.
func deleting(t *testing.T) Model {
	t.Helper()
	return feed(t, loadedModel(t), jobs.ChangedMsg{
		Runs: actRunning(t, jobs.KindDelete, actCtx, "alpha"), Context: actCtx,
	})
}

func TestColumnZeroIsTheActivityColumn(t *testing.T) {
	c := explorerColumns()[0]
	if c.Title != "" || c.Sizing != datatable.SizingFixed || c.MinWidth != datatable.IconColumnWidth {
		t.Errorf("column 0 = %q/%v/%d, want untitled SizingFixed IconColumnWidth", c.Title, c.Sizing, c.MinWidth)
	}
	if c.Indicator == nil {
		t.Error("column 0 is not built by datatable.IndicatorColumn")
	}
	if c.Less != nil || c.Search != nil {
		t.Errorf("column 0 declares Less=%v Search=%v, want neither", c.Less != nil, c.Search != nil)
	}
	m := loadedModel(t)
	shapes := m.table.Shapes()
	if len(shapes) == 0 || !shapes[0].Indicator {
		t.Errorf("the live tree has no activity column 0: %+v", shapes)
	}
}

//
// The mapping lives here rather than in the router for the reason Reporter
// exists: "a project whose template failed still exists" is this package's
// vocabulary, and a router that knew it would grow a branch per view.

func (m GroupCreatedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindCreate, Target: m.Target, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "create failed — check logs"
	}
	return t
}

func (m ProjectCreatedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindCreate, Target: m.Target, State: jobs.ItemDone}
	switch {
	case m.Error != nil && m.TemplateUnavailable:
		// Nothing was created: the template was fetched first, and could not be.
		t.State = jobs.ItemFailed
		t.Detail = "template unavailable — nothing was created"
	case m.Error != nil:
		t.State = jobs.ItemFailed
		t.Detail = "create failed — check logs"
	case m.TemplateError != nil:
		// The project exists, empty, but what was asked for was a repository
		// with a template in it: the run says it did not get there rather than
		// reading as a success. The row still settles (handleProjectCreated).
		t.State = jobs.ItemFailed
		t.Detail = "created empty — the template's commit failed"
	}
	return t
}

func (m DeleteCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindDelete, Target: m.Target, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "delete failed — check logs"
	}
	return t
}

// Compile-time proof that every message reporting on registered work can be
// applied to the registry. One added without it would be routed, would update
// the view, and would leave its row spinning for the life of the view — which
// is precisely the failure the registry exists to remove.
var (
	_ jobs.Reporter = GroupCreatedMsg{}
	_ jobs.Reporter = ProjectCreatedMsg{}
	_ jobs.Reporter = DeleteCompleteMsg{}
)
		return ProjectCreatedMsg{Repository: repo, Target: target}
	}
}

// handleGroupCreated resolves the placeholder row in place.
//
// No refresh: the forge has just told us what it made, so re-listing the whole
// tree to learn it would empty the table for the length of a second round trip.
// It is also what stops a create outliving a context switch from reloading the
// tree of the context it switched to.
//
// A failure goes to the footer rather than to m.error, which would replace the
// tree with an error screen — the one place the removed row cannot be seen.
func (m Model) handleGroupCreated(msg GroupCreatedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [explorer] create namespace: %v", msg.Error)
		m.settleCreating(msg.Target, nil)
		return m, m.footer.Error("Failed to create " + msg.Target + " — check logs")
	}

	node := nodeFromNamespace(msg.Namespace, nil)
	m.settleCreating(msg.Target, node)
	m.levelChanged(node.Parent)
	m.selectRow(node.FullPath)
	return m, indexCreated(node)
}

// handleProjectCreated resolves the placeholder row in place. See
// handleGroupCreated for why there is no refresh.
func (m Model) handleProjectCreated(msg ProjectCreatedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [explorer] create repository: %v", msg.Error)
		m.settleCreating(msg.Target, nil)
		if msg.TemplateUnavailable {
			return m, m.footer.Error("Could not fetch the template — " + msg.Target + " was not created. Check logs")
		}
		return m, m.footer.Error("Failed to create " + msg.Target + " — check logs")
	}

	// The project exists whatever the template did, so the row settles either
	// way; only the message differs.
	node := nodeFromRepository(msg.Repository, nil)
	m.settleCreating(msg.Target, node)
	m.levelChanged(node.Parent)
	m.selectRow(node.FullPath)

	if msg.TemplateError != nil {
		log.Printf("ERROR [explorer] apply template: %v", msg.TemplateError)
		return m, tea.Batch(indexCreated(node),
			m.footer.Warn(fmt.Sprintf("%s created empty: the template's commit failed — check logs", node.Name)))
	}
	return m, indexCreated(node)
}

